Lemma ls_ok_2 : forall (M M' : word -> option byte) (Sg : Z -> Prop),
  (forall a, Sg a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  (forall a, PMLA.IMG_RO_LO IC <= a < PMLA.IMG_RO_HI IC \/ PMLA.in_foot IC a -> ~ (SEA.GD <= a < SEA.GD + 2) -> ~ (SEA.AXT <= a < SEA.AXT + 544) -> Sg a) ->
  PMLA.ls_ok (hl_segs L) IC PML.LS1 M ->
  atexit_state_at (hl_segs L) (PMLA.ATEXIT_TAB IC) M' (PMLA.HS0 IC ++ PMLA.ls_atexit IC PML.LS2) ->
